// BalanceCheck.js (Frontend)
import React, { useState, useEffect } from 'react';
import axios from 'axios';
//import './BalanceCheck.css'; // Create this CSS file

function BalanceCheck() {
    const [balance, setBalance] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const email = localStorage.getItem('email');


    useEffect(() => {
        const fetchBalance = async () => {
            try {
                const response = await axios.get(`/balance/${email}`); // Use the new route
                setBalance(response.data.balance); // Access balance directly from response.data.balance


            } catch (error) {
                console.error("Error:", error);
                // Handle errors (display message, etc.)
            } finally {
                setLoading(false);
            }
        };



        if (email) {
            fetchBalance();
        } else {
            setError("User not logged in.");
            setLoading(false);

        }


    }, [email]);


    if (loading) {
        return <div>Loading balance...</div>;
    }


    if (error) {
        return <div>Error: {error}</div>;
    }

    return (
        <div className="balance-check-container">
            <h2>Your Account Balance</h2>
            <p>Current Balance: ${balance}</p>


        </div>
    );

}


export default BalanceCheck;
